import sys


def main():
    show_line = False
    show_word = False
    show_char = False
    file_arg = None

    args = sys.argv[1:]
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-'):
            for ch in arg[1:]:
                if ch == 'l':
                    show_line = True
                elif ch == 'w':
                    show_word = True
                elif ch == 'c':
                    show_char = True
                else:
                    print(f"Unknown flag: {ch}", file=sys.stderr)
                    sys.exit(1)
        else:
            file_arg = arg
        i += 1

    if not show_line and not show_word and not show_char:
        show_line = True
        show_word = True
        show_char = True

    if file_arg is None or file_arg == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(file_arg, 'rb') as f:
            data = f.read()

    num_chars = len(data)
    num_words = len(data.decode().split())
    # A final line with no trailing newline still counts as a line.
    text = data.decode()
    num_lines = text.count('\n')
    if text and not text.endswith('\n'):
        num_lines += 1

    results = []
    if show_line:
        results.append(str(num_lines))
    if show_word:
        results.append(str(num_words))
    if show_char:
        results.append(str(num_chars))

    print(' '.join(results))


if __name__ == '__main__':
    main()
